let b = a;
b = 10;
console.log(a, b); // 5 10

const obj1 = { value: 5 };
const obj2 = obj1;
obj2.value = 10;
console.log(obj1.value, obj2.value); // 10 10

const user = { name: "Ana" };
user.name = "Leo"; // allowed: changing a property, not reassigning the variable
console.log(user.name); // "Leo"

